//! RupeeCoin Mobile Bridge
//!
//! This crate provides the Rust crypto core for the Flutter mobile wallet.
//! The public API in `api.rs` is annotated for flutter_rust_bridge codegen.
//!
//! Build steps:
//!   1. `cargo build && cargo test`     — verify Rust side independently
//!   2. `flutter_rust_bridge_codegen generate`  — produce Dart + Rust glue
//!   3. `flutter build apk --release`           — build the Android APK

// Expose to flutter_rust_bridge codegen (processed at build time, not compile time).
pub mod api;
mod keystore;

// Generated by `flutter_rust_bridge_codegen generate` — do not edit.
mod frb_generated;
